//! 🧪️ Actual scene aliases preserve one stable source and exact final physical retirement.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,OriginalFailureContext};
fn clock()->Option<u64>{Some(1000)}
fn native<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,|cx|{let deadline=cx.original_absolute_deadline_us();cx.with_original_work_loan(1,deadline,run)}));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
fn retire(scene:&mut Option<FlowComposedScene>,retirement:&mut RetainedCloneClose,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant){for turn in 0..200{if scene.is_none()&&retirement.is_empty(){return}native(caller,decoder,g,|cx|cx.with_original_retirement(|cx|{let d=if retirement.is_empty(){retirement.next_owner_demands::<FlowComposedScene>(scene.is_some(),&None,g.maximum_copy_bytes)?}else{retirement.demands(g.maximum_copy_bytes)?};close_original_retained_step(cx,d,|grant|if retirement.is_empty(){let turn=retirement.begin_granted(scene,grant);RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:turn.work}}else{retirement.step_granted(grant)})?;Ok(())}));assert!(turn+1<200,"original scene retirement exhausted actual one-fuel frames")}}
#[test]
fn original_composed_scene_alias_preserves_stable_source_and_one_fuel_physical_custody(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️scene.json")).unwrap();
 for items in [1,512]{for case in fixture["cases"].as_array().unwrap(){
  let g=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:4096,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:4096};let mut caller=OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128*1024*1024,maximum_capacity_bytes:256*1024*1024,maximum_release_bytes:512*1024*1024,maximum_depth:4096},clock,1500,32768);let mut decoder=OriginalJobDecodeOwner::empty();native(&mut caller,&mut decoder,g,|_|Ok(()));
  let mut original=Some(HostSnapshot{schema:String::new(),camera:CameraJson{x:0.0,y:0.0,zoom:1.0},widgets:Vec::new(),synapses:Vec::new(),layout:flow::OrderedMap::new()});let mut owner=None;let mut alias=None;let mut identity=None;let mut retirement=RetainedCloneClose::default();
  for(event,count)in case["events"].as_array().unwrap().iter().zip(case["counts"].as_array().unwrap()){
   match event.as_str().unwrap(){
    "birth"=>{let d=FlowComposedScene::birth_demand();for denied_grant in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let denied=FlowComposedScene::admit(&mut original,denied_grant);assert_eq!(denied.work,0);assert!(denied.result.unwrap().is_none());assert!(original.is_some());}native(&mut caller,&mut decoder,g,|cx|{let d=FlowComposedScene::birth_demand();let grant=cx.retained_grant();let mut accepted=None;admit_original_construction(cx,&mut accepted,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},|_|{let turn=FlowComposedScene::admit(&mut original,grant);RetainedWorkOutcome{result:turn.result.and_then(|output|{let Some((scene,p))=output else{return Err(invalid())};owner=Some(scene);Ok(((),p))}),work:turn.work}})?;Ok(())});identity=Some(owner.as_ref().unwrap().source().source_identity())},
    "alias"=>{let scene=owner.as_ref().unwrap();let d=scene.alias_demand();for denied_grant in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let before=std::sync::Arc::strong_count(scene.original.as_ref().unwrap());let denied=scene.retain(denied_grant);assert_eq!(denied.work,0);assert!(denied.result.unwrap().is_none());assert_eq!(std::sync::Arc::strong_count(scene.original.as_ref().unwrap()),before);}native(&mut caller,&mut decoder,g,|cx|{let turn=owner.as_ref().unwrap().retain(cx.retained_grant());cx.consume_fuel(turn.work);let Some((scene,p))=turn.result? else{return Err(invalid().into())};alias=Some(scene);cx.consume_retained(p)?;Ok(())})},
    "retire-owner"=>retire(&mut owner,&mut retirement,&mut caller,&mut decoder,g),
    "retire-alias"=>retire(&mut alias,&mut retirement,&mut caller,&mut decoder,g),
    _=>unreachable!()
   }
   let live=owner.as_ref().or(alias.as_ref());assert_eq!(usize::from(owner.is_some())+usize::from(alias.is_some()),count.as_u64().unwrap()as usize);if let Some(live)=live{assert_eq!(Some(live.source().source_identity()),identity)}
  }
  assert!(original.is_none()&&owner.is_none()&&alias.is_none()&&retirement.is_empty());while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(g.maximum_copy_bytes)?;decoder.close_on_source(cx)?;Ok(())})).unwrap();}caller.retire(g);
 }}
}

struct OriginalModelLease<T:semio_framework_value::RetireOwned+Sync>(std::sync::Arc<T>);
impl<T:semio_framework_value::RetireOwned+Sync>semio_framework_value::RetireOwned for OriginalModelLease<T>{
 fn retirement(self)->Box<dyn semio_framework_value::retirement::RetirementCursor>{Box::new(semio_framework_value::retirement::arc_custody::SharedControlledRetirement::lease(self.0))}
 fn retirement_birth_bytes(&self)->Option<usize>{Some(semio_framework_value::retirement::arc_custody::shared_retirement_birth_bytes::<T>())}
 fn controlled_retirement_supported()->bool{true}
}
fn original_model<T:semio_framework_value::RetireOwned+Sync>(original:&std::sync::Arc<T>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant)->semio_framework_value::retained_clone::RetainedCloneSource<T,OriginalModelLease<T>>{
 use semio_framework_value::retained_clone::{RetainedCloneSource,RetainedCloneSourceAdmission};let mut admission=RetainedCloneSourceAdmission::new(OriginalModelLease(std::sync::Arc::clone(original)),(),|source:&OriginalModelLease<T>|source.0.as_ref());let mut output:Option<RetainedCloneSource<T,OriginalModelLease<T>>>=None;
 for turn in 0..200{native(caller,decoder,g,|cx|{let d=if admission.phase()=="ready"{fixed()}else{admission.next_demand()?};if !cx.retained_work_can_enter(d){return Ok(())}let turn=if admission.phase()=="ready"{admission.take_output(&mut output,cx.retained_grant())}else{admission.advance(cx.retained_grant())};semio_framework_job::receive_original_retained_work(cx,turn)?;Ok(())});if admission.terminal_is_empty(){break}assert!(turn+1<200)}assert!(admission.terminal_is_empty());drop(admission);output.unwrap()
}
#[test]
fn original_composed_source_refuses_distinct_real_callers_with_identical_business_labels(){
 use semio_framework_value::RetireOwned;
 fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128*1024*1024,maximum_capacity_bytes:256*1024*1024,maximum_release_bytes:512*1024*1024,maximum_depth:4096},clock,1500,32768)}
 let parent=std::sync::Arc::new(FlowSnapshot::default());let child=std::sync::Arc::new(Child::default());let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:4096};let mut first=caller();let mut second=caller();let mut first_decode=OriginalJobDecodeOwner::empty();let mut second_decode=OriginalJobDecodeOwner::empty();native(&mut first,&mut first_decode,g,|_|Ok(()));native(&mut second,&mut second_decode,g,|_|Ok(()));
 let mut parent_source=original_model(&parent,&mut first,&mut first_decode,g);let mut child_source=original_model(&child,&mut first,&mut first_decode,g);let mut work=FlowComposedSourceWork::new();
 assert!(!native(&mut first,&mut first_decode,g,|cx|work.step(parent_source.try_borrow()?,Some(child_source.try_borrow()?),cx)));let binding=work.original_binding().unwrap();let before=(work.phase,work.index,work.binding.map(|binding|(binding.parent_reference,binding.child_reference,binding.document,binding.schema,binding.schema_length,binding.child,binding.nodes,binding.node_count,binding.edges,binding.edge_count)));
 let failure=native(&mut second,&mut second_decode,g,|cx|Ok(work.step(parent_source.try_borrow()?,Some(child_source.try_borrow()?),cx))).unwrap_err();assert_eq!(second.receipt(),RetainedCloneProgress::default());assert_eq!(failure.primary_value().unwrap().kind,ValueRefusalKind::InvariantViolated);assert_eq!((work.phase,work.index,work.binding.map(|binding|(binding.parent_reference,binding.child_reference,binding.document,binding.schema,binding.schema_length,binding.child,binding.nodes,binding.node_count,binding.edges,binding.edge_count))),before);assert_eq!(work.original_binding(),Some(binding));failure.retire_cold();
 work.begin_close();for turn in 0..10000{if work.terminal_is_empty(){break}native(&mut first,&mut first_decode,g,|cx|cx.with_original_retirement(|cx|{work.close_step(cx)?;Ok(())}));assert!(turn+1<10000)}assert!(work.terminal_is_empty());drop(work);
 for turn in 0..10000{if parent_source.terminal_is_empty()&&child_source.terminal_is_empty(){break}native(&mut first,&mut first_decode,g,|cx|cx.with_original_retirement(|cx|{let turn=if !child_source.terminal_is_empty(){child_source.close_step(cx.retained_grant())}else{parent_source.close_step(cx.retained_grant())};semio_framework_job::receive_original_retained_work(cx,turn)?;Ok(())}));assert!(turn+1<10000)}assert!(parent_source.terminal_is_empty()&&child_source.terminal_is_empty());drop(parent_source);drop(child_source);
 for(caller,decoder)in[(&mut first,&mut first_decode),(&mut second,&mut second_decode)]{while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(g.maximum_copy_bytes)?;decoder.close_on_source(cx)?;Ok(())})).unwrap();}caller.retire(g);}
 parent.retire_cold();child.retire_cold();
}
